const output = $json.output || '';
const webhookData = $('Webhook').item.json;
const recipient = webhookData.body.data.key.remoteJid;

let cleanOutput = output
  .replace(/\[SEND_TO_SALES_COORDINATOR\]/g, '')
  .replace(/\[SEND_TO_TECHNICAL_SUPPORT\]/g, '')
  .replace(/\[SEND_COLOR_CARD\]/g, '')
  .replace(/\[SEND_CATALOG\]/g, '')
  .replace(/\[SEND_PRICE_LIST_IMAGE\]/g, '')
  .replace(/\[SEND_PRODUCT_IMAGES:[^\]]+\]/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return {
  json: {
    output: output,
    recipient: recipient,
    recipientNumber: recipient.split('@')[0],
    formatted_output: cleanOutput
  }
};

const coordinatorNumber = '905539644020@s.whatsapp.net';
const formatOutput = $('Format Output').item.json;
const customerNumber = formatOutput.recipientNumber;
const output = formatOutput.output || '';

const beforeTag = output.split('[SEND_TO_SALES_COORDINATOR]')[0].trim();

let productInfo = '';
const lines = beforeTag.split('\n').map(l => l.trim()).filter(l => l.length > 0);

for (let line of lines) {
  if (line.match(/^.+ - \d+ adet$/i)) {
    productInfo = line;
    break;
  }
}

if (!productInfo) {
  for (let line of lines) {
    if (line.toLowerCase().includes('adet') && line.length < 100) {
      productInfo = line;
      break;
    }
  }
}

if (!productInfo) {
  const products = ['Combo Cadillac', 'Tower Reformer', 'Basic Reformer', 'Cadillac', 'Infinity Reformer', 'Metal Reformer', 'Katlanabilir Reformer', 'Barrel', 'Chair', 'Spine Corrector'];
  for (let line of lines) {
    for (let product of products) {
      if (line.includes(product)) {
        productInfo = line;
        break;
      }
    }
    if (productInfo) break;
  }
}

if (!productInfo) {
  productInfo = lines.slice(-3).join(' | ');
}

const message = `YENI SATIS TALEBI\n\nTalep: ${productInfo}\n\nMusteri: ${customerNumber}\n\nTam Mesaj:\n${beforeTag}\n\nLutfen en kisa surede musteriyi arayin.`;

return {
  json: {
    recipient: coordinatorNumber,
    message: message
  }
};

